        shayariItem(954, "बाबू मैं छोटा हूँ पर मेरा प्यार तितना बड़ा है ना,\nकि अगर तुम बोलो तो पूरा मैगी का पैकेट तुम्हारे नाम है ना।", "निब्बा-निब्बी स्पेशल", cat, "मैगी लव"),
        shayariItem(955, "मेले पिलु, तम्हाली आवाज में कोई मीठी सी घंटी है,\nसुनते ही मेरे अंदर की सारी सुस्ती भागती है बंटी है।", "निब्बा-निब्बी स्पेशल", cat, "आवाज़"),
        shayariItem(956, "सुबह-शाम बस एक ही गाना गुनगुनाता हूँ आजकल,\n'मेला बाबू, मेला सोना' बोल-बोल के घर वालों को पकाता हूँ आजकल।", "निब्बा-निब्बी स्पेशल", cat, "मस्ती"),
        shayariItem(957, "तुम जब हँसते-हँसते मेरी नाक खींचते हो बाबू,\nतब ऐसा लगता है जैसे दुनिया की सारी टॉफ़ी मिल गई हो तानू।", "निब्बा-निब्बी स्पेशल", cat, "टॉफ़ी"),
        shayariItem(958, "मेले नटखट, तुम इतना शैतान क्यों बन गए हो,\nकभी मेरा पेन छुपाते हो तो कभी मेला लंच खा गए हो।", "निब्बा-निब्बी स्पेशल", cat, "शैतानी"),
        shayariItem(959, "अग़ल मैं रूठ जाऊँ तो तुम मुजे किंडर जॉय लाकर दोगे क्या,\nमेरे छोटे से दिल को अपने प्यार के खिलौने से सजाओगे क्या।", "निब्बा-निब्बी स्पेशल", cat, "किंडर जॉय"),
        shayariItem(960, "बाबू तू मेला कार्टून नेटवर्क है मैं तेला पोगो,\nहम दोनों साथ हों तो बाकी दुनिया को बोलो टाटा-गो-गो।", "निब्बा-निब्बी स्पेशल", cat, "कार्टून"),
        shayariItem(961, "मेले कद्दू, तुम आज बहुत हैंडसम लग लहे हो नई शर्ट में,\nबच के रहना कहीं कोई चुरा न ले जाए तुझे इस भीड़-भड़क्के में।", "निब्बा-निब्बी स्पेशल", cat, "कद्दू"),
        shayariItem(962, "तू मेली प्याली सी बिंदी है मैं तेला काजल,\nदोनों मिल जाएं तो बन जाए इश्क़ का क्यूट सा बादल।", "निब्बा-निब्बी स्पेशल", cat, "शृंगार"),
        shayariItem(963, "बाबू ने आज पानी पिया कि नहीं, याद दिलाने आया हूँ,\nताली टेंशन छोड़ दे मैं तेरे लिए फैंटा की बोतल लाया हूँ।", "निब्बा-निब्बी स्पेशल", cat, "केयर"),
        shayariItem(964, "मेली मैना, तू इतना मीठा बोलती है सुबह से रात,\nमन करता है तेरी हर बात रिकॉर्ड करके सुनता रहूँ दिन-रात।", "निब्बा-निब्बी स्पेशल", cat, "मैना"),
        shayariItem(965, "तेले पापा मान जाएं बस एक बार हमारी जोड़ी को,\nपिल देख लेना कैसे सजाऊँगा मैं अपनी निब्बी गोरी को।", "निब्बा-निब्बी स्पेशल", cat, "शादी सपना"),
        shayariItem(966, "मेले रसगुल्ले, तुम इत्ते सॉफ्ट औल स्वीट हो,\nकि बिना शुगर के भी मेरी धड़कनों की बीट हो।", "निब्बा-निब्बी स्पेशल", cat, "रसगुल्ला"),
        shayariItem(967, "बाबू जब तुम मुझे 'इतूत सा' बोलकर चिढ़ाते हो,\nतब गुस्सा आता है पर तुम्हारी स्माइल देख पिघल जाते हो।", "निब्बा-निब्बी स्पेशल", cat, "चिढ़ाना"),
        shayariItem(968, "तुमने मेरी हुडी पहन ली और वापस भी नहीं दी यार,\nअब मैं भी तुम्हारा क्लिप चुरा लूँगा यही है सच्चा प्यार।", "निब्बा-निब्बी स्पेशल", cat, "हुडी"),
        shayariItem(969, "मेली गुलुमोलु, तुम बहोत ज़्यादा सोती हो दिन भर,\nथोड़ा सा जाग जाया करो मेरे बाबू, मुजे बोरियत होती है फिर।", "निब्बा-निब्बी स्पेशल", cat, "नींद"),
        shayariItem(970, "दिल में तितली नहीं पूरा चिड़ियाघर उड़ता है मेले,\nजब तुम स्लो मोशन में चलके आती हो सामने अकेले।", "निब्बा-निब्बी स्पेशल", cat, "तितलियाँ"),
        shayariItem(971, "मेले छोटू, तुम चाहे जितनी मर्ज़ी बड़ा बनने का नाटक कर लो,\nमेरे सामने तो हमेशा रोने वाले छोटे बच्चे ही रहोगे चलो।", "निब्बा-निब्बी स्पेशल", cat, "छोटू"),
        shayariItem(972, "बाबू आज तितनी गर्मी है पर तुम फिर भी कूल लगते हो,\nमेले छोटे से दिमाग़ पर हर वक़्त सिर्फ़ तुम ही तुम रहते हो।", "निब्बा-निब्बी स्पेशल", cat, "कूल"),
        shayariItem(973, "मेली जलेबी, तुम सीधी बात कभी मत करना यार,\nतेरी इसी टेढ़ी-मेढ़ी अदा पर तो आता है बेशुमार प्यार।", "निब्बा-निब्बी स्पेशल", cat, "जलेबी"),
        shayariItem(974, "तेरे नाम का पहला अक्षर मैंने कॉपी के आख़िरी पन्ने पर लिखा,\nटीचर ने देख लिया तो बोला 'ये किसका नाम तूतला-तूतला दिखा?'", "निब्बा-निब्बी स्पेशल", cat, "स्कूल"),
        shayariItem(975, "बाबू मेला ना सर दर्द हो रहा है बहुत तेज़ अभी,\nआके माथा दबा दो ना, वरना मैं सो जाऊँगा ऐसे ही तभी।", "निब्बा-निब्बी स्पेशल", cat, "नाज़-नखरा"),
        shayariItem(976, "मेले मिठू, तुम दिन भर बकबक करते हो फिर भी अच्छा लगता है,\nजिस दिन तुम चुप हो जाओ उस दिन घर भी सुना-सुना लगता है।", "निब्बा-निब्बी स्पेशल", cat, "मिठू"),
        shayariItem(977, "अगर किसी ने मेरी जानू को रुलाया तो खैर नहीं,\nचाहे वो कोई भी हो, मेरे बाबू से बढ़कर कोई गैर नहीं।", "निब्बा-निब्बी स्पेशल", cat, "प्रोटेक्शन"),
        shayariItem(978, "मेली बिल्ली, तुम इतना नाखून क्यों दिखाती हो हर बात पे,\nकभी तो प्यार से म्याऊँ बोल के बैठ जाया करो पास में।", "निब्बा-निब्बी स्पेशल", cat, "म्याऊँ"),
        shayariItem(979, "बाबू तुझे पता है आज मैंने तेरे लिए गाना गाया बाथरूम में,\nमम्मी बाहर से चिल्लाईं 'कौन रो रहा है इतना ज़ोर से झूम के?'", "निब्बा-निब्बी स्पेशल", cat, "फनी"),
        shayariItem(980, "मेले पुचका, तुम इत्ते गोल-मटोल और प्यारे हो,\nमेरी अँधेरी रातों के सबसे चमकते हुए तारे हो।", "निब्बा-निब्बी स्पेशल", cat, "तारा"),
        shayariItem(981, "तुम 'आई हेट यू' बोलकर फिर दस सेकंड में 'मिस यू' लिखते हो,\nसच्ची बताओ मेरे बाबू, तुम इतनी एक्टिंग कहाँ से सीखते हो।", "निब्बा-निब्बी स्पेशल", cat, "नौटंकी"),
        shayariItem(982, "मेले मोगली, तुम जंगल में भी रहोगे तो मैं आ जाऊँगा,\nतुम्हारे लिए रोज़ ताज़े आम और जामुन तोड़कर लाऊँगा।", "निब्बा-निब्बी स्पेशल", cat, "मोगली"),
        shayariItem(983, "जब तक सूरज चाँद रहेगा, मेरे बाबू का नखरा आबाद रहेगा,\nचाहे जितनी चॉकलेट खानी पड़े, ये निब्बा हमेशा तैयार रहेगा।", "निब्बा-निब्बी स्पेशल", cat, "वादा"),
        shayariItem(984, "मेली गुड़िया की मुस्कान किसी लॉटरी से कम नहीं,\nवो हँस दे तो मेरे पास दुनिया का कोई ग़म नहीं।", "निब्बा-निब्बी स्पेशल", cat, "मुस्कान"),
        shayariItem(985, "बाबू तेरा 'ओके बेबी' सुनने को पूरा दिन तरसता हूँ,\nऔर तू है कि इमोजी भेजकर ऑफ़लाइन भाग जाता है तूल।", "निब्बा-निब्बी स्पेशल", cat, "इमोजी"),
        shayariItem(986, "मेले काजू कतली, तुम शादी में सबसे ज़्यादा चमकती हो,\nजब भी लड्डू खाती हो छोटे बच्चों जैसी लगती हो।", "निब्बा-निब्बी स्पेशल", cat, "मिठाई"),
        shayariItem(987, "एक हाथ में समोसा और दूसरे हाथ में तेरा हाथ हो,\nबस इतनी सी ख्वाहिश है कि हर शाम ऐसी ही बात हो।", "निब्बा-निब्बी स्पेशल", cat, "समोसा डेट"),
        shayariItem(988, "मेले चीकू, तुम कभी बड़े मत होना मेरे सामने,\nये बचपना और तोतली बातें ही तो सबसे प्यारी लगती हैं जान में।", "निब्बा-निब्बी स्पेशल", cat, "बचपना"),
        shayariItem(989, "बाबू आज मैंने तुम्हें सपने में किसी और से बात करते देखा,\nसुबह उठते ही पहले तीन कॉल करके सारा हिसाब ले लिया।", "निब्बा-निब्बी स्पेशल", cat, "सपना"),
        shayariItem(990, "तेरी मेरी जोड़ी राम-सिया नहीं बल्कि टॉम एंड जेरी जैसी है,\nलड़ते भी खूब हैं पर एक-दूसरे के बिना एक पल भी नहीं रह सकते हैं।", "निब्बा-निब्बी स्पेशल", cat, "टॉम एंड जेरी"),
        shayariItem(991, "मेले छोटे पटाखे, तुम दिवाली से पहले ही इतना शोर मचाते हो,\nजब भी मैं बात न सुनूँ तो पूरा घर सिर पर उठाते हो।", "निब्बा-निब्बी स्पेशल", cat, "पटाखा"),
        shayariItem(992, "बाबू मुझे गिफ़्ट में आईफ़ोन नहीं बस एक लाल गुलाब चाहिए,\nऔर हर संडे तुम्हारे साथ साइकिल पर गोलगप्पे खाने का हिसाब चाहिए।", "निब्बा-निब्बी स्पेशल", cat, "सिंपल लव"),
        shayariItem(993, "मेली शहद की मक्खी, तुम मीठी भी हो और डंक भी मारती हो,\nपर सच कहूँ तो मेरे दिल के सबसे करीब तुम ही रहती हो।", "निब्बा-निब्बी स्पेशल", cat, "हनीबी"),
        shayariItem(994, "आज फिर तेरे घर के बाहर से साइकिल लेकर तीन चक्कर लगाए,\nतेरे भाई ने देख लिया तो मैं दूध लेने आया हूँ बोल के भाग आए।", "निब्बा-निब्बी स्पेशल", cat, "निब्बा मस्ती"),
        shayariItem(995, "मेले बबू ने आज नया हेयरस्टाइल बनाया है बहुत शानदार,\nलगता है आज फिर से होने वाला है मुझ पर प्यार का वार।", "निब्बा-निब्बी स्पेशल", cat, "लुक"),
        shayariItem(996, "बाबू तुम चाहे जितने मोटे हो जाओ मैं फिर भी प्यार करूँगा,\nबस अपनी प्लेट से दो मोमोज़ मुझे भी शेयर कर दिया करोगे ना।", "निब्बा-निब्बी स्पेशल", cat, "शेयरिंग"),
        shayariItem(997, "मेली तानू, तेरा नाम सुनते ही मुँह पे बड़ी वाली बत्तीसी आ जाती है,\nमम्मी पूछती हैं 'फ़ोन में क्या देख के हँस रहा है?' तो बात बनानी पड़ती है।", "निब्बा-निब्बी स्पेशल", cat, "बत्तीसी"),
        shayariItem(998, "बड़े लोगों का प्यार होगा बड़ी-बड़ी गाड़ियों वाला,\nअपना तो बाबू-सोना और साइकिल की डबल सवारी वाला।", "निब्बा-निब्बी स्पेशल", cat, "देसी प्यार"),
        shayariItem(999, "तुम रूठे रहे तो मैं तारे गिन-गिन के सो जाऊँगा,\nसुबह उठके फिर से 'सॉरी मेले बाबू' वाला मैसेज भेज पाऊँगा।", "निब्बा-निब्बी स्पेशल", cat, "मनाना"),
        shayariItem(1000, "आख़िरी बात बस इतनी है मेले प्याले से पोक़ेमॉन,\nतुम ही हो मेरी दुनिया, मेरा सोना, मेरा बाबू औल मेरा डॉन।", "निब्बा-निब्बी स्पेशल", cat, "फॉरएवर")
    )
}
